import React, { useEffect, useState } from "react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";

/**
 * Replaces literal HTML <br>, <br/>, <br /> tags with actual React line breaks.
 * This guarantees table cells and text generated by LLMs with embedded breaks render cleanly
 * without exposing raw '<br>' tags to the user.
 */
function formatWithBreaks(children) {
    if (!children) return children;
    if (typeof children === "string") {
        const parts = children.split(/<br\s*\/?>/gi);
        if (parts.length === 1) return children;
        return parts.map((part, idx) =>
            idx === 0 ? part : (
                <React.Fragment key={idx}>
                    <br />
                    {part}
                </React.Fragment>
            )
        );
    }
    if (Array.isArray(children)) {
        return children.map((c, i) => (
            <React.Fragment key={i}>
                {formatWithBreaks(c)}
            </React.Fragment>
        ));
    }
    return children;
}

function AnswerBlock({
    answer = "",
    sources = [],
    error = false,
    errorMessage = "",
    loading = false,
    isNew = false,
    onRetry = null
}) {
    const defaultErrorText =
        errorMessage || "Sorry, something went wrong while retrieving legal information. Please check your connection or try again.";

    // Only typewrite if this specific message is newly generated
    const [displayedText, setDisplayedText] = useState(isNew ? "" : answer);
    const [isTyping, setIsTyping] = useState(isNew && Boolean(answer));
    const [activeSource, setActiveSource] = useState(null);

    useEffect(() => {
        if (loading || error) {
            setDisplayedText("");
            setIsTyping(false);
            return;
        }

        if (!isNew) {
            setDisplayedText(answer);
            setIsTyping(false);
            return;
        }

        if (!answer) {
            setDisplayedText("");
            setIsTyping(false);
            return;
        }

        let index = 0;
        setDisplayedText("");
        setIsTyping(true);

        const step = Math.max(1, Math.floor(answer.length / 150));
        const interval = setInterval(() => {
            index += step;
            if (index >= answer.length) {
                setDisplayedText(answer);
                setIsTyping(false);
                clearInterval(interval);
            } else {
                setDisplayedText(answer.substring(0, index));
            }
        }, 15);

        return () => clearInterval(interval);
    }, [answer, loading, error, isNew]);

    if (loading) {
        return (
            <div className="flex items-center gap-2 py-3 px-1 text-sm text-blue-600 dark:text-blue-400">
                <span className="h-2 w-2 rounded-full bg-blue-600 dark:bg-blue-400 animate-pulse" />
                <span
                    className="h-2 w-2 rounded-full bg-blue-600 dark:bg-blue-400 animate-pulse"
                    style={{ animationDelay: "150ms" }}
                />
                <span
                    className="h-2 w-2 rounded-full bg-blue-600 dark:bg-blue-400 animate-pulse"
                    style={{ animationDelay: "300ms" }}
                />
                <span className="ml-2 text-xs font-mono uppercase tracking-wider text-slate-500 dark:text-slate-400">
                    Consulting NyayKosh Legal Knowledge Base...
                </span>
            </div>
        );
    }

    if (error) {
        return (
            <div className="my-2 rounded-xl border border-red-200 bg-red-50 p-4 text-xs text-red-700 dark:border-red-900/50 dark:bg-red-950/30 dark:text-red-300">
                <div className="flex items-start justify-between gap-3">
                    <div className="flex items-start gap-2">
                        <span className="font-bold text-red-500 text-sm">⚠️</span>
                        <p className="leading-relaxed">{defaultErrorText}</p>
                    </div>
                    {onRetry && (
                        <button
                            onClick={onRetry}
                            className="shrink-0 rounded-lg bg-red-100 px-3 py-1 text-xs font-semibold text-red-800 hover:bg-red-200 dark:bg-red-900/60 dark:text-red-200 transition"
                        >
                            Retry
                        </button>
                    )}
                </div>
            </div>
        );
    }

    const contentToRender = isTyping ? displayedText : answer;

    return (
        <div className="w-full text-slate-900 dark:text-slate-100 transition-colors">
            {/* Markdown Answer Rendering */}
            <div className="prose prose-sm dark:prose-invert max-w-none">
                <ReactMarkdown
                    remarkPlugins={[remarkGfm]}
                    components={{
                        // Table rendering with horizontal scroll wrapper
                        table: ({ node, ...props }) => (
                            <div className="my-4 overflow-x-auto rounded-xl border border-slate-200 dark:border-white/[0.1] shadow-sm">
                                <table
                                    className="min-w-full divide-y divide-slate-200 dark:divide-white/[0.1] text-left text-xs sm:text-sm"
                                    {...props}
                                />
                            </div>
                        ),
                        thead: ({ node, ...props }) => (
                            <thead
                                className="bg-slate-100 text-slate-800 dark:bg-white/[0.06] dark:text-slate-200 font-semibold"
                                {...props}
                            />
                        ),
                        tbody: ({ node, ...props }) => (
                            <tbody
                                className="divide-y divide-slate-100 bg-white dark:divide-white/[0.05] dark:bg-[#16191D]"
                                {...props}
                            />
                        ),
                        th: ({ node, children, ...props }) => (
                            <th className="px-4 py-3 font-semibold tracking-wider text-slate-900 dark:text-white" {...props}>
                                {formatWithBreaks(children)}
                            </th>
                        ),
                        td: ({ node, children, ...props }) => (
                            <td className="px-4 py-3 text-slate-800 dark:text-slate-300 whitespace-normal leading-relaxed align-top" {...props}>
                                {formatWithBreaks(children)}
                            </td>
                        ),
                        // Typography formatting with br tag replacement
                        h1: ({ node, children, ...props }) => (
                            <h1 className="mt-4 mb-2 text-xl font-bold tracking-tight text-slate-900 dark:text-white" {...props}>
                                {formatWithBreaks(children)}
                            </h1>
                        ),
                        h2: ({ node, children, ...props }) => (
                            <h2 className="mt-4 mb-2 text-lg font-semibold text-blue-600 dark:text-blue-400" {...props}>
                                {formatWithBreaks(children)}
                            </h2>
                        ),
                        h3: ({ node, children, ...props }) => (
                            <h3 className="mt-3 mb-1 text-base font-semibold text-slate-900 dark:text-slate-200" {...props}>
                                {formatWithBreaks(children)}
                            </h3>
                        ),
                        p: ({ node, children, ...props }) => (
                            <p className="my-2.5 leading-7 text-xs sm:text-sm text-slate-800 dark:text-slate-200" {...props}>
                                {formatWithBreaks(children)}
                            </p>
                        ),
                        ul: ({ node, ...props }) => (
                            <ul className="my-2 ml-5 list-disc space-y-1.5 text-xs sm:text-sm text-slate-800 dark:text-slate-200" {...props} />
                        ),
                        ol: ({ node, ...props }) => (
                            <ol className="my-2 ml-5 list-decimal space-y-1.5 text-xs sm:text-sm text-slate-800 dark:text-slate-200" {...props} />
                        ),
                        li: ({ node, children, ...props }) => (
                            <li className="leading-relaxed" {...props}>
                                {formatWithBreaks(children)}
                            </li>
                        ),
                        strong: ({ node, children, ...props }) => (
                            <strong className="font-semibold text-slate-900 dark:text-white" {...props}>
                                {formatWithBreaks(children)}
                            </strong>
                        ),
                        blockquote: ({ node, children, ...props }) => (
                            <blockquote
                                className="my-3 rounded-r-xl border-l-4 border-blue-500 bg-blue-50/70 p-3 italic text-slate-700 dark:bg-blue-950/20 dark:text-slate-300 text-xs sm:text-sm"
                                {...props}
                            >
                                {formatWithBreaks(children)}
                            </blockquote>
                        ),
                        code: ({ node, inline, ...props }) =>
                            inline ? (
                                <code
                                    className="rounded bg-slate-100 px-1.5 py-0.5 font-mono text-xs text-blue-700 dark:bg-slate-800 dark:text-blue-300"
                                    {...props}
                                />
                            ) : (
                                <pre className="my-3 overflow-x-auto rounded-xl bg-slate-900 p-4 font-mono text-xs text-slate-100 dark:bg-black/60">
                                    <code {...props} />
                                </pre>
                            )
                    }}
                >
                    {contentToRender}
                </ReactMarkdown>

                {isTyping && (
                    <span className="inline-block h-4 w-1 animate-pulse bg-blue-500 ml-1 align-middle" />
                )}
            </div>

            {/* Verified Legal Sources Section */}
            {!isTyping && sources && sources.length > 0 && (
                <div className="mt-5 pt-3.5 border-t border-slate-200 dark:border-white/[0.08]">
                    <div className="flex items-center gap-2 mb-2">
                        <span className="font-mono text-[10px] uppercase tracking-[0.18em] text-slate-500 dark:text-slate-400">
                            Verified Legal Sources ({sources.length})
                        </span>
                    </div>

                    <div className="flex flex-wrap gap-2">
                        {sources.map((source, index) => (
                            <button
                                key={index}
                                onClick={() => setActiveSource(activeSource === source ? null : source)}
                                className={`rounded-lg border px-3 py-1.5 font-mono text-xs transition flex items-center gap-1.5 ${
                                    activeSource === source
                                        ? "border-blue-500 bg-blue-50 text-blue-700 dark:bg-blue-950/40 dark:text-blue-300"
                                        : "border-slate-200 bg-slate-50 text-slate-700 hover:border-blue-300 hover:bg-slate-100 dark:border-white/[0.1] dark:bg-[#1D2125] dark:text-slate-300 dark:hover:border-blue-500/40"
                                }`}
                                title="Click to view citation details"
                            >
                                <span className="text-[10px] text-blue-500">§</span>
                                <span>{source}</span>
                            </button>
                        ))}
                    </div>

                    {activeSource && (
                        <div className="mt-3 p-3 rounded-xl border border-blue-200 bg-blue-50 text-xs text-slate-800 dark:border-blue-900/40 dark:bg-blue-950/20 dark:text-slate-200 flex items-center justify-between">
                            <div>
                                <span className="font-semibold text-blue-700 dark:text-blue-400">Referenced Legal Source: </span>
                                <span>{activeSource}</span>
                                <p className="text-[11px] text-slate-600 dark:text-slate-400 mt-0.5">
                                    Retrieved from the centralized Indian legal document knowledge base.
                                </p>
                            </div>
                            <button
                                onClick={() => setActiveSource(null)}
                                className="text-slate-400 hover:text-slate-700 dark:hover:text-white px-2 py-1 text-xs"
                            >
                                ✕
                            </button>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
}

export default AnswerBlock;
